from typing import Iterable

def in_level(values: Iterable[int], n: int) -> bool:
    """Test finite sampled membership in D_n."""
    return all(value % (2 ** n) == 0 for value in values)

def table(values: list[int], maximum: int) -> list[tuple[int, bool]]:
    return [(n, in_level(values, n)) for n in range(maximum + 1)]

if __name__ == "__main__":
    for values in ([0, 0, 0], [8, -24, 40], [64, -192, 320]):
        print(values, table(list(values), 8))

from typing import Mapping, Sequence
Monomial = Mapping[int, int]

def monomial_in_V(monomial: Monomial, n: int) -> bool:
    return any(i < n and exponent > 0 for i, exponent in monomial.items())

def polynomial_in_V(poly: Sequence[Monomial], n: int) -> bool:
    return all(monomial_in_V(term, n) for term in poly)

if __name__ == "__main__":
    for n in range(7):
        witness = {n: 1}
        print(n, monomial_in_V(witness, n), monomial_in_V(witness, n + 1))

def generators(level: int, variable_count: int | None) -> tuple[int, ...]:
    stop = level if variable_count is None else min(level, variable_count)
    return tuple(range(stop))

def chain(variable_count: int, levels: int) -> list[tuple[int, ...]]:
    return [generators(n, variable_count) for n in range(levels + 1)]

if __name__ == "__main__":
    finite = chain(4, 8)
    for n, rung in enumerate(finite):
        changed = n == 0 or rung != finite[n - 1]
        print(f"n={n}: {rung}, changed={changed}")

