def v2(value: int) -> int | None:
    if value == 0: return None
    value = abs(value); n = 0
    while value % 2 == 0:
        value //= 2; n += 1
    return n

def filtration_depth(values: Iterable[int]) -> int | None:
    finite = [v2(x) for x in values if x != 0]
    return min(finite) if finite else None

from typing import Mapping, Sequence

def in_variable_ideal(poly: Sequence[Mapping[int, int]], n: int) -> bool:
    """Every monomial must contain a positive power of some x_i with i<n."""
    return all(any(i < n and e > 0 for i, e in monomial.items())
               for monomial in poly)

def coordinate_chain(variable_count: int | None, levels: int) -> list[tuple[int, ...]]:
    result: list[tuple[int, ...]] = []
    for n in range(levels + 1):
        stop = n if variable_count is None else min(n, variable_count)
        result.append(tuple(range(stop)))
    return result

